#include <cstdio>
#include <vector>

struct Holder {
  std::vector<int> v{1, 2, 3};
  ~Holder() { std::puts("~Holder"); }
  const std::vector<int>& items() const { return v; }
};

Holder make() { return {}; }

int main() {
  for (int x : make().items()) std::printf("%d ", x);
  std::puts("done");
}

